def _clean(value) -> str:
    return " ".join(str(value or "").strip().split())


def _norm(value) -> str:
    text = _clean(value).upper().replace("Đ", "D")
    text = unicodedata.normalize("NFD", text)
    text = "".join(ch for ch in text if unicodedata.category(ch) != "Mn")
    return " ".join(re.sub(r"[^A-Z0-9]+", " ", text).split())


def _commune_base(value) -> str:
    text = _norm(value)
    for prefix in ("PHUONG ", "XA ", "THI TRAN "):
        if text.startswith(prefix):
            return text[len(prefix):].strip()
    return text


def _decode_dataset(encoded: str) -> dict:
    raw = gzip.decompress(base64.b64decode(encoded.encode("ascii")))
    return json.loads(raw.decode("utf-8"))


def _parse_date(value):
    text = _clean(value)
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            return datetime.strptime(text, fmt).date()
        except Exception:
            pass
    return None


def _status_priority(label) -> int:
    return {
        "CHUYEN DEN": 100,
        "DANG LAM VIEC": 90,
        "DA BIET PHAI": 60,
        "DA DIEU DONG": 50,
        "CHO NGHI HUU": 40,
        "DA CHUYEN DI": 20,
        "DA NGHI HUU": 10,
        "THOI VIEC": 5,
    }.get(_norm(label), 1)


def _is_current(label) -> bool:
    return _norm(label) in {"DANG LAM VIEC", "CHUYEN DEN"}


def _map_status(label) -> str:
    n = _norm(label)
    if n in {"CHUYEN DEN", "DANG LAM VIEC"}:
        return "DANG_LAM_VIEC"
    if "NGHI HUU" in n:
        return "NGHI_HUU"
    if "THOI VIEC" in n or "NGHI VIEC" in n:
        return "NGHI_VIEC"
    if "CHUYEN DI" in n or "DIEU DONG" in n:
        return "CHUYEN_DI"
    return "TAM_NGHI"


def _map_position(value) -> str:
    n = _norm(value)
    if "CAN BO QUAN LY" in n:
        return "CBQL"
    if "NHAN VIEN" in n:
        return "NHAN_VIEN"
    return "GIAO_VIEN"


def _map_employment(value) -> str:
    n = _norm(value)
    if "KHONG XAC DINH THOI HAN" in n:
        return "BIEN_CHE"
    if "VIEN CHUC" in n or "CONG CHUC" in n:
        return "HOP_DONG_LAM_VIEC"
    if "HOP DONG" in n or "THINH GIANG" in n:
        return "HOP_DONG_LAO_DONG"
    return "CHUA_XAC_DINH"


def _map_qualification(value) -> str:
    n = _norm(value)
    if "TIEN SI" in n:
        return "TIEN_SI"
    if "THAC SI" in n:
        return "THAC_SI"
    if "DAI HOC" in n:
        return "DAI_HOC"
    if "CAO DANG" in n:
        return "CAO_DANG"
    if "TRUNG CAP" in n:
        return "TRUNG_CAP"
    if n:
        return "KHAC"
    return "CHUA_XAC_DINH"


def _map_teaching_level(group, position_group) -> str:
    if position_group != "GIAO_VIEN":
        return "KHONG_DAY"
    n = _norm(group)
    if "NHA TRE" in n:
        return "NHA_TRE"
    if "MAU GIAO" in n:
        return "MAU_GIAO"
    return "KHONG_DAY"


def _map_teaching_age(group) -> str:
    # Nguồn chỉ ghi Nhà trẻ/Mẫu giáo, không chỉ rõ lớp 3–4 hay 5 tuổi.
    n = _norm(group)
    if "NHA TRE" in n:
        return "NHA_TRE"
    return "KHONG_XAC_DINH"


def _institution_group(name) -> str:
    n = _norm(name)
    if any(x in n for x in ("NHOM TRE", "LOP MAM NON", "CO SO", "GDMN DOC LAP")):
        return "CO_SO_GDMN_DOC_LAP"
    return "TRUONG_MAM_NON"


def _read_text(path: Path) -> str:
    if not path.exists():
        raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")
    return path.read_text(encoding="utf-8-sig")


def _backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []
    for rel in FILES_TO_BACKUP:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})
        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def _restore(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def _patch_router(text: str) -> str:
    if "BAI_13B_6_V1_4_MN_SCOPE_START" in text:
        return text

    if "BAI_13B_6_V1_3_MN_SCOPE_START" not in text:
        raise RuntimeError(
            "Chưa tìm thấy Bài 13B-6 V1.3 trong report_inputs.py. "
            "Dừng cài để tránh sửa nhầm phiên bản."
        )

    pattern = (
        r"# === BAI_13B_6_V1_3_MN_SCOPE_START ===.*?"
        r"# === BAI_13B_6_V1_3_MN_SCOPE_END ==="
    )
    text, count = re.subn(
        pattern,
        MN_SCOPE_V14.strip(),
        text,
        count=1,
        flags=re.S,
    )
    if count != 1:
        raise RuntimeError("Không thay được phạm vi trường Mầm non V1.3.")

    marker = "# === BAI_13B_6_V1_4_MN_SCOPE_END ==="
    text = text.replace(
        marker,
        marker + MN_HELPERS_V14,
        1,
    )

    route_pattern = (
        r'@router\.get\("/doi-ngu/nhap-mn-01-gv", response_class=HTMLResponse\)\n'
        r'def gv_report_input_page\(.*?'
        r'(?=\n@router\.post\("/doi-ngu/nhap-mn-01-gv"\))'
    )
    text, count = re.subn(
        route_pattern,
        GV_ROUTE_V14.strip() + "\n",
        text,
        count=1,
        flags=re.S,
    )
    if count != 1:
        raise RuntimeError("Không thay được màn hình dữ liệu MN-01-GV.")

    return text


def _remove_team_report_links(text: str) -> str:
    # Bài 13B-6 V1.4 FINAL:
    # Báo cáo chính thức chỉ đặt tại menu 5. Báo cáo.
    # Menu Đội ngũ và CSVC chỉ giữ chức năng nhập/kiểm tra dữ liệu.
    patterns = [
        # Đội ngũ
        r'\s*<a href="/bao-cao\?report_type=PCGD_MN_01_GV_2025" role="menuitem">\s*4\.1\.4\. Báo cáo MN-01-GV\s*</a>',
        r'\s*<a href="/bao-cao\?report_type=PCGD_TH_01_GV_2025" role="menuitem">\s*4\.2\.3\. Báo cáo TH-01-GV\s*</a>',
        r'\s*<a href="/bao-cao\?report_type=PCGD_THCS_M5_2025" role="menuitem">\s*4\.3\.3\. Báo cáo THCS-01-GV\s*</a>',

        # Cơ sở vật chất
        r'\s*<a href="/bao-cao\?report_type=PCGD_MN_01_CSVC_2025" role="menuitem">\s*CSVC\.1\.6\. Báo cáo MN-01-CSVC\s*</a>',
        r'\s*<a href="/bao-cao\?report_type=PCGD_TH_01_CSVC_2025" role="menuitem">\s*CSVC\.2\.5\. Báo cáo TH-01-CSVC\s*</a>',
        r'\s*<a href="/bao-cao\?report_type=PCGD_THCS_CSVC_2025" role="menuitem">\s*CSVC\.3\.5\. Báo cáo THCS-01-CSVC\s*</a>',
    ]

    for pattern in patterns:
        text = re.sub(pattern, "\n", text, count=1, flags=re.S)

    if "BAI_13B_6_V1_4_REPORT_SCOPE_CASCADE_START" not in text:
        text = text.rstrip() + "\n\n" + REPORT_CASCADE_SCRIPT.strip() + "\n"

    return text


def _verify_source() -> None:
    router_text = _read_text(ROUTER)
    menu_text = _read_text(MENU)
    template_text = _read_text(GV_TEMPLATE)

    required = [
        ("MN scope", "BAI_13B_6_V1_4_MN_SCOPE_START", router_text),
        ("MN display", "BAI_13B_6_V1_4_MN_DISPLAY_START", router_text),
        ("MN route", "display_rows", router_text),
        ("MN template", "MN-01-GV – Đội ngũ giáo viên Mầm non", template_text),
        ("MN template staff", "Danh sách nhân sự của trường", template_text),
        ("report cascade", "BAI_13B_6_V1_4_REPORT_SCOPE_CASCADE_START", menu_text),
    ]
    for label, marker, text in required:
        if marker not in text:
            raise RuntimeError(f"Kiểm tra nguồn không đạt: {label} / {marker}")

    for forbidden in (
        "4.1.4. Báo cáo MN-01-GV",
        "4.2.3. Báo cáo TH-01-GV",
        "4.3.3. Báo cáo THCS-01-GV",
        "CSVC.1.6. Báo cáo MN-01-CSVC",
        "CSVC.2.5. Báo cáo TH-01-CSVC",
        "CSVC.3.5. Báo cáo THCS-01-CSVC",
    ):
        if forbidden in menu_text:
            raise RuntimeError(f"Chưa xóa menu báo cáo trùng: {forbidden}")


def _check_python_and_jinja() -> None:
    import subprocess
    from jinja2 import Environment, FileSystemLoader

    subprocess.run(
        [sys.executable, "-m", "py_compile", str(ROUTER)],
        cwd=PROJECT,
        check=True,
    )

    env = Environment(
        loader=FileSystemLoader(str(APP / "templates"))
    )
    for name in (
        "partials/dropdown_menu_v1.html",
        "report_inputs/gv_mn01.html",
        "report_inputs/csvc_mn01.html",
        "report_inputs/structured_school_form.html",
    ):
        env.get_template(name)


def _import_mn_data() -> dict:
    from sqlalchemy import func, select
    from app.database import Base, SessionLocal, engine
    from app.models import Commune, School, SchoolYear
    from app.report_input_models import (
        SchoolMn01CsvcInput,
        SchoolMn01GvInput,
        SchoolNetworkYearData,
    )
    from app.staff_models import (
        SchoolStaffYearSummary,
        StaffMember,
        StaffYearRecord,
    )

    Base.metadata.create_all(bind=engine)

    network = _decode_dataset(MN_NETWORK_DATA_B64)
    staff = _decode_dataset(MN_STAFF_DATA_B64)
    source_year_code = str(
        network.get("source_year")
        or staff.get("source_year")
        or "2025-2026"
    )
    network_rows = list(network.get("records") or [])
    staff_rows = list(staff.get("records") or [])

    stats = {
        "network_source_rows": len(network_rows),
        "staff_source_rows": len(staff_rows),
        "schools_created": 0,
        "schools_reused": 0,
        "schools_moved_commune": 0,
        "network_created": 0,
        "network_updated": 0,
        "staff_members_created": 0,
        "staff_members_reused": 0,
        "staff_records_created": 0,
        "staff_records_updated_auto": 0,
        "staff_records_enriched": 0,
        "staff_school_unmatched": 0,
        "active_staff": 0,
        "active_teachers": 0,
        "summary_created": 0,
        "summary_updated": 0,
        "gv_input_created": 0,
        "gv_input_updated": 0,
        "csvc_created": 0,
        "csvc_enriched": 0,
        "unmatched_communes": set(),
    }

    db = SessionLocal()
    try:
        year = db.scalar(
            select(SchoolYear).where(
                SchoolYear.code == source_year_code
            )
        )
        if year is None:
            year = SchoolYear(
                code=source_year_code,
                name=f"Năm học {source_year_code}",
                is_active=True,
            )
            db.add(year)
            db.flush()

        communes = list(
            db.scalars(
                select(Commune).where(
                    Commune.is_active.is_(True)
                )
            ).all()
        )
        full_map = defaultdict(list)
        base_map = defaultdict(list)
        for commune in communes:
            full_map[_norm(commune.name)].append(commune)
            base_map[_commune_base(commune.name)].append(commune)

        def find_commune(name):
            name = _clean(name)
            if not name:
                return None
            exact = full_map.get(_norm(name), [])
            if len(exact) == 1:
                return exact[0]
            base = base_map.get(_commune_base(name), [])
            if len(base) == 1:
                return base[0]
            return None

        schools = list(db.scalars(select(School)).all())
        schools_by_code = {
            _clean(s.code): s
            for s in schools
            if _clean(s.code)
        }
        schools_by_name = defaultdict(list)
        for school in schools:
            schools_by_name[_norm(school.name)].append(school)

        school_by_source_key = {}
        network_by_school_id = {}

        # 1. Mạng lưới Mầm non: dùng file nguồn làm chuẩn xã/phường và mã trường.
        for row in network_rows:
            code = _clean(row.get("school_code"))
            school_name = _clean(row.get("school_name"))
            commune_name = _clean(row.get("commune_name"))
            if not code or not school_name:
                continue

            commune = find_commune(commune_name)
            if commune is None:
                stats["unmatched_communes"].add(commune_name)
                continue

            school = schools_by_code.get(code)

            if school is None:
                candidates = list(
                    schools_by_name.get(
                        _norm(school_name),
                        [],
                    )
                )
                same_commune = [
                    s for s in candidates
                    if int(s.commune_id) == int(commune.id)
                ]

                if len(same_commune) == 1:
                    school = same_commune[0]
                elif len(candidates) == 1:
                    school = candidates[0]

            if school is None:
                school = School(
                    commune_id=int(commune.id),
                    code=code,
                    name=school_name,
                    is_active=True,
                )
                db.add(school)
                db.flush()
                schools_by_code[code] = school
                schools_by_name[_norm(school_name)].append(school)
                stats["schools_created"] += 1
            else:
                stats["schools_reused"] += 1

                if int(school.commune_id) != int(commune.id):
                    school.commune_id = int(commune.id)
                    stats["schools_moved_commune"] += 1

                if not _clean(school.name):
                    school.name = school_name

                # Chỉ bổ sung mã chuẩn nếu trường hiện tại chưa có mã.
                if not _clean(school.code):
                    school.code = code
                    schools_by_code[code] = school

                school.is_active = True

            school_by_source_key[
                (_norm(commune_name), _norm(school_name))
            ] = school
            network_by_school_id[int(school.id)] = row

            rec = db.scalar(
                select(SchoolNetworkYearData).where(
                    SchoolNetworkYearData.school_id == int(school.id),
                    SchoolNetworkYearData.school_year_id == int(year.id),
                    SchoolNetworkYearData.level_code == "MN",
                )
            )
            if rec is None:
                rec = SchoolNetworkYearData(
                    school_id=int(school.id),
                    school_year_id=int(year.id),
                    level_code="MN",
                )
                db.add(rec)
                stats["network_created"] += 1
            else:
                stats["network_updated"] += 1

            rec.data_json = json.dumps(
                row.get("data") or {},
                ensure_ascii=False,
                separators=(",", ":"),
            )
            rec.source_name = "Thong_ke_mang_luoi_lop_HS_GV_MN.xlsx"

        db.commit()

        # 2. Chọn bản ghi tốt nhất của mỗi mã nhân sự.
        grouped = defaultdict(list)
        for row in staff_rows:
            code = _clean(row.get("staff_code"))
            if code:
                grouped[code].append(row)

        best_staff = {}
        for code, rows in grouped.items():
            best = max(
                rows,
                key=lambda item: (
                    _status_priority(item.get("status")),
                    int(item.get("source_row") or 0),
                ),
            )
            school = school_by_source_key.get(
                (
                    _norm(best.get("commune_name")),
                    _norm(best.get("school_name")),
                )
            )
            if school is None:
                stats["staff_school_unmatched"] += 1
                continue
            best_staff[code] = (best, school)

        members_by_ministry = {
            _clean(m.ministry_staff_code): m
            for m in db.scalars(select(StaffMember)).all()
            if _clean(m.ministry_staff_code)
        }
        members_by_code = {
            _clean(m.code): m
            for m in db.scalars(select(StaffMember)).all()
            if _clean(m.code)
        }
        used_codes = set(members_by_code)
        max_member_id = db.scalar(
            select(func.max(StaffMember.id))
        ) or 0

        def next_internal_code():
            nonlocal max_member_id
            while True:
                max_member_id += 1
                candidate = f"NS-{max_member_id:08d}"
                if candidate not in used_codes:
                    used_codes.add(candidate)
                    return candidate

        year_records = {
            (int(r.staff_member_id), int(r.school_year_id)): r
            for r in db.scalars(
                select(StaffYearRecord)
            ).all()
        }

        current_rows_by_school = defaultdict(list)

        for index, (ministry_code, pair) in enumerate(
            best_staff.items(),
            start=1,
        ):
            source, school = pair

            member = (
                members_by_ministry.get(ministry_code)
                or members_by_code.get(ministry_code)
            )
            if member is None:
                member = StaffMember(
                    code=next_internal_code(),
                    ministry_staff_code=ministry_code,
                    full_name=_clean(source.get("full_name")) or ministry_code,
                    date_of_birth=_parse_date(source.get("date_of_birth")),
                    gender=_clean(source.get("gender")) or None,
                    ethnic_group=_clean(source.get("ethnic_group")) or None,
                    is_active=True,
                )
                db.add(member)
                db.flush()
                members_by_ministry[ministry_code] = member
                stats["staff_members_created"] += 1
            else:
                stats["staff_members_reused"] += 1
                if not _clean(getattr(member, "ministry_staff_code", None)):
                    member.ministry_staff_code = ministry_code
                if not _clean(getattr(member, "ethnic_group", None)) and _clean(source.get("ethnic_group")):
                    member.ethnic_group = _clean(source.get("ethnic_group"))
                if not _clean(getattr(member, "gender", None)) and _clean(source.get("gender")):
                    member.gender = _clean(source.get("gender"))
                if getattr(member, "date_of_birth", None) is None:
                    member.date_of_birth = _parse_date(source.get("date_of_birth"))

            position_group = _map_position(source.get("position"))
            teaching_level = _map_teaching_level(
                source.get("teaching_group"),
                position_group,
            )
            key = (int(member.id), int(year.id))
            record = year_records.get(key)

            notes = (
                f"Nguồn MN {source_year_code}"
                f" | Trạng thái nguồn: {_clean(source.get('status'))}"
            )

            if record is None:
                record = StaffYearRecord(
                    staff_member_id=int(member.id),
                    school_year_id=int(year.id),
                    school_id=int(school.id),
                    status_code=_map_status(source.get("status")),
                    position_group=position_group,
                    position_title=(
                        _clean(source.get("position_title"))
                        or _clean(source.get("position"))
                        or None
                    ),
                    employment_type=_map_employment(source.get("employment")),
                    teaching_level=teaching_level,
                    teaching_age_group=_map_teaching_age(source.get("teaching_group")),
                    teaching_subject=None,
                    main_specialty=None,
                    staff_evaluation=_clean(source.get("evaluation")) or None,
                    source_level="MN",
                    source_status_label=_clean(source.get("status")) or None,
                    qualification_level=_map_qualification(source.get("qualification")),
                    qualification_standard="CHUA_XAC_DINH",
                    professional_standard="CHUA_DANH_GIA",
                    notes=notes,
                    is_active=True,
                )
                db.add(record)
                db.flush()
                year_records[key] = record
                stats["staff_records_created"] += 1
            else:
                is_auto_mn = (
                    str(getattr(record, "source_level", "") or "").upper() == "MN"
                    or "NGUON MN " in _norm(getattr(record, "notes", None))
                )

                if is_auto_mn:
                    record.school_id = int(school.id)
                    record.status_code = _map_status(source.get("status"))
                    record.position_group = position_group
                    record.position_title = (
                        _clean(source.get("position_title"))
                        or _clean(source.get("position"))
                        or record.position_title
                    )
                    record.employment_type = _map_employment(source.get("employment"))
                    record.teaching_level = teaching_level
                    if record.teaching_age_group == "KHONG_XAC_DINH":
                        record.teaching_age_group = _map_teaching_age(source.get("teaching_group"))
                    record.staff_evaluation = _clean(source.get("evaluation")) or record.staff_evaluation
                    record.source_level = "MN"
                    record.source_status_label = _clean(source.get("status")) or None
                    if record.qualification_level == "CHUA_XAC_DINH":
                        record.qualification_level = _map_qualification(source.get("qualification"))
                    record.notes = notes
                    record.is_active = True
                    stats["staff_records_updated_auto"] += 1
                else:
                    changed = False
                    for attr, value in (
                        ("staff_evaluation", _clean(source.get("evaluation")) or None),
                        ("source_level", "MN"),
                        ("source_status_label", _clean(source.get("status")) or None),
                    ):
                        if not _clean(getattr(record, attr, None)) and value:
                            setattr(record, attr, value)
                            changed = True
                    if record.qualification_level == "CHUA_XAC_DINH":
                        record.qualification_level = _map_qualification(source.get("qualification"))
                        changed = True
                    if changed:
                        stats["staff_records_enriched"] += 1

            if _is_current(source.get("status")):
                current_rows_by_school[int(school.id)].append(source)
                stats["active_staff"] += 1
                if position_group == "GIAO_VIEN":
                    stats["active_teachers"] += 1

            if index % 4000 == 0:
                db.flush()

        db.commit()

        # 3. Đồng bộ số liệu mạng lưới vào các bảng đầu vào MN năm nguồn.
        for school_id, source_row in network_by_school_id.items():
            data = source_row.get("data") or {}
            school = db.get(School, school_id)
            if school is None:
                continue

            total_classes = int(data.get("class_total") or 0)
            preschool_3_4 = (
                int(data.get("class_3_4y") or 0)
                + int(data.get("class_4_5y") or 0)
            )
            preschool_5 = int(data.get("class_5_6y") or 0)

            summary = db.scalar(
                select(SchoolStaffYearSummary).where(
                    SchoolStaffYearSummary.school_id == school_id,
                    SchoolStaffYearSummary.school_year_id == int(year.id),
                )
            )
            if summary is None:
                summary = SchoolStaffYearSummary(
                    school_id=school_id,
                    school_year_id=int(year.id),
                    institution_group=_institution_group(school.name),
                    total_groups_classes=total_classes,
                    preschool_classes_3_4=preschool_3_4,
                    preschool_classes_5=preschool_5,
                    notes=f"Tự động từ mạng lưới MN {source_year_code}",
                )
                db.add(summary)
                stats["summary_created"] += 1
            else:
                auto_summary = (
                    not _clean(summary.notes)
                    or "TU DONG TU MANG LUOI MN" in _norm(summary.notes)
                )
                if auto_summary:
                    summary.institution_group = _institution_group(school.name)
                    summary.total_groups_classes = total_classes
                    summary.preschool_classes_3_4 = preschool_3_4
                    summary.preschool_classes_5 = preschool_5
                    summary.notes = f"Tự động từ mạng lưới MN {source_year_code}"
                    stats["summary_updated"] += 1

            source_staff = current_rows_by_school.get(school_id, [])
            ethnic_count = sum(
                1
                for item in source_staff
                if _clean(item.get("ethnic_group"))
                and _norm(item.get("ethnic_group")) != "KINH"
            )

            gv_input = db.scalar(
                select(SchoolMn01GvInput).where(
                    SchoolMn01GvInput.school_id == school_id,
                    SchoolMn01GvInput.school_year_id == int(year.id),
                )
            )
            if gv_input is None:
                gv_input = SchoolMn01GvInput(
                    school_id=school_id,
                    school_year_id=int(year.id),
                    ethnic_staff_count=ethnic_count,
                    notes=f"Tự động từ danh sách đội ngũ MN {source_year_code}",
                )
                db.add(gv_input)
                stats["gv_input_created"] += 1
            elif (
                not _clean(gv_input.notes)
                or "TU DONG TU DANH SACH DOI NGU MN" in _norm(gv_input.notes)
            ):
                gv_input.ethnic_staff_count = ethnic_count
                gv_input.notes = f"Tự động từ danh sách đội ngũ MN {source_year_code}"
                stats["gv_input_updated"] += 1

            csvc = db.scalar(
                select(SchoolMn01CsvcInput).where(
                    SchoolMn01CsvcInput.school_id == school_id,
                    SchoolMn01CsvcInput.school_year_id == int(year.id),
                )
            )
            if csvc is None:
                csvc = SchoolMn01CsvcInput(
                    school_id=school_id,
                    school_year_id=int(year.id),
                    facility_count=1,
                    nursery_group_count=(
                        int(data.get("class_3_12m") or 0)
                        + int(data.get("class_12_24m") or 0)
                        + int(data.get("class_24_36m") or 0)
                    ),
                    preschool_class_3_4_count=preschool_3_4,
                    preschool_class_5_count=preschool_5,
                    total_classroom_count=int(data.get("classroom_total") or 0),
                    notes=f"Tự động từ mạng lưới MN {source_year_code}; chỉ điền các chỉ tiêu có nguồn xác định.",
                )
                db.add(csvc)
                stats["csvc_created"] += 1
            else:
                changed = False
                safe_values = {
                    "facility_count": 1,
                    "nursery_group_count": (
                        int(data.get("class_3_12m") or 0)
                        + int(data.get("class_12_24m") or 0)
                        + int(data.get("class_24_36m") or 0)
                    ),
                    "preschool_class_3_4_count": preschool_3_4,
                    "preschool_class_5_count": preschool_5,
                    "total_classroom_count": int(data.get("classroom_total") or 0),
                }
                for attr, value in safe_values.items():
                    if getattr(csvc, attr, None) is None:
                        setattr(csvc, attr, value)
                        changed = True
                if changed:
                    stats["csvc_enriched"] += 1

        db.commit()

        stats["unmatched_communes"] = sorted(stats["unmatched_communes"])
        stats["mn_network_total"] = int(
            db.scalar(
                select(func.count(SchoolNetworkYearData.id)).where(
                    SchoolNetworkYearData.level_code == "MN",
                    SchoolNetworkYearData.school_year_id == int(year.id),
                )
            ) or 0
        )
        return stats
    finally:
        db.close()


def main() -> int:
    print("=" * 96)
    print("BÀI 13B-6 V1.4")
    print("HOÀN THIỆN MẦM NON + LỌC BÁO CÁO + GỌN MENU ĐỘI NGŨ")
    print("=" * 96)
    print("")
    print("1. ĐỘI NGŨ:")
    print(" - Xóa các nhánh Báo cáo khỏi menu Đội ngũ và CSVC để tránh trùng với 5. Báo cáo.")
    print("")
    print("2. BÁO CÁO:")
    print(" - Chọn Năm học/Loại báo cáo/Xã-phường sẽ nạp lại danh sách trường.")
    print(" - Không giữ danh sách trường của phạm vi cũ.")
    print("")
    print("3. MẦM NON:")
    print(" - Nhập mạng lưới 2025-2026: 891 trường/cơ sở.")
    print(" - Nhập danh sách nguồn: 20.903 dòng, 20.514 mã nhân sự duy nhất.")
    print(" - Sửa đúng xã/phường của trường theo file mạng lưới.")
    print(" - MN-01-GV hiển thị thống nhất với Tiểu học/THCS.")
    print(" - Dữ liệu 2025-2026 chỉ làm tham chiếu cho 2026-2027 cho tới khi bấm Lưu.")
    print("")

    for path in (ROUTER, MENU, GV_TEMPLATE, DB):
        if not path.exists():
            raise RuntimeError(f"Không tìm thấy tệp bắt buộc: {path}")

    router_before = _read_text(ROUTER)
    if "BAI_13B_6_V1_3_MN_SCOPE_START" not in router_before:
        raise RuntimeError(
            "Chưa có Bài 13B-6 V1.3. Hãy dừng và không cài bản này."
        )
    if "BAI_13B_6_V1_2_NETWORK_DATA_START" not in router_before:
        raise RuntimeError("Chưa có nền dữ liệu mạng lưới Bài 13B-6 V1.2 FINAL.")

    manifest = _backup_files()

    try:
        ROUTER.write_text(
            _patch_router(router_before),
            encoding="utf-8",
        )
        MENU.write_text(
            _remove_team_report_links(_read_text(MENU)),
            encoding="utf-8",
        )
        GV_TEMPLATE.write_text(
            GV_TEMPLATE_V14,
            encoding="utf-8",
        )

        _check_python_and_jinja()
        stats = _import_mn_data()
        _verify_source()

        for cache in APP.rglob("__pycache__"):
            if cache.is_dir():
                shutil.rmtree(cache, ignore_errors=True)

        print("")
        print("KẾT QUẢ DỮ LIỆU MẦM NON:")
        for key in (
            "network_source_rows",
            "staff_source_rows",
            "schools_created",
            "schools_reused",
            "schools_moved_commune",
            "network_created",
            "network_updated",
            "staff_members_created",
            "staff_members_reused",
            "staff_records_created",
            "staff_records_updated_auto",
            "staff_records_enriched",
            "staff_school_unmatched",
            "active_staff",
            "active_teachers",
            "mn_network_total",
        ):
            print(f" - {key}: {stats.get(key, 0)}")

        if stats.get("unmatched_communes"):
            print(" - Xã/phường chưa khớp:", ", ".join(stats["unmatched_communes"]))
        else:
            print(" - Xã/phường chưa khớp: 0")

        print("")
        print("CAI DAT BAI 13B-6 V1.4 FINAL THANH CONG")
        print("Backup:", BACKUP)
        return 0

    except Exception:
        traceback.print_exc()
        print("")
        print("CÓ LỖI - ĐANG KHÔI PHỤC MÃ NGUỒN VÀ DATABASE...")
        _restore(manifest)
        print("ĐÃ KHÔI PHỤC VỀ TRƯỚC BÀI 13B-6 V1.4.")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
